var minimumIndex = function(nums) {
    const n = nums.length;
    const counts = new Map();
    let dominant = nums[0];
    let total = 0;
    for (const x of nums) {
        const cnt = (counts.get(x) || 0) + 1;
        counts.set(x, cnt);
        if (cnt > total) {
            total = cnt;
            dominant = x;
        }
    }
    let leftCount = 0;
    for (let i = 0; i < n - 1; i++) {
        if (nums[i] === dominant) {
            leftCount++;
        }
        const rightCount = total - leftCount;
        const leftLen = i + 1;
        const rightLen = n - leftLen;
        if (leftCount * 2 > leftLen && rightCount * 2 > rightLen) {
            return i;
        }
    }
    return -1;
};
